CREATE TABLE categories (
  id  NUMBER(4) PRIMARY KEY,
  nom VARCHAR2(40) NOT NULL UNIQUE
);

CREATE TABLE produits (
  id           NUMBER(6) PRIMARY KEY,
  nom          VARCHAR2(60) NOT NULL,
  prix         NUMBER(10,2) CHECK (prix > 0),
  categorie_id NUMBER(4) REFERENCES categories(id)
);

INSERT INTO categories (id, nom) VALUES (1, 'Alimentaire');
